module sticky_reg_bank_64bit (
  input [63:0] \dec-word-in ,
  input \word-flush ,
  input \master-reset ,
  output [63:0] presence
);
  wire [63:0] s0;
  wire [63:0] presence_temp;
  wire [63:0] s1;
  // REG_64
  DIG_Register_BUS #(
    .Bits(64)
  )
  DIG_Register_BUS_i0 (
    .D( s0 ),
    .C( \word-flush  ),
    .en( 1'b1 ),
    .Q( presence_temp )
  );
  assign s1 = (presence_temp | \dec-word-in );
  Mux_2x1_NBits #(
    .Bits(64)
  )
  Mux_2x1_NBits_i1 (
    .sel( \master-reset  ),
    .in_0( s1 ),
    .in_1( 64'b0 ),
    .out( s0 )
  );
  assign presence = presence_temp;
endmodule

module token_presence (
  input [7:0] \word-slot-addr ,
  input \word-flush ,
  input \punct-q ,
  input \punct-excl ,
  input \punct-long ,
  input \master-sent-rst ,
  output [2:0] \punct-presence ,
  output [63:0] \word-presence-0-63 ,
  output [63:0] \word-presence-64-127 ,
  output [63:0] \word-presence-128-191 ,
  output [63:0] \word-presence-192-255 
);
  wire [63:0] s0;
  wire [63:0] s1;
  wire [63:0] s2;
  wire [63:0] s3;
  wire s4;
  wire s5;
  wire s6;
  demux_decoder_8to256 demux_decoder_8to256_i0 (
    .\word-slot-addr ( \word-slot-addr  ),
    .\O192-255 ( s0 ),
    .\O128-191 ( s1 ),
    .\O64-127 ( s2 ),
    .\O0-63 ( s3 )
  );
  RS_ff_as RS_ff_as_i1 (
    .R( \master-sent-rst  ),
    .S( \punct-q  ),
    .Q( s4 )
  );
  RS_ff_as RS_ff_as_i2 (
    .R( \master-sent-rst  ),
    .S( \punct-excl  ),
    .Q( s5 )
  );
  RS_ff_as RS_ff_as_i3 (
    .R( \master-sent-rst  ),
    .S( \punct-long  ),
    .Q( s6 )
  );
  // bank0-63
  sticky_reg_bank_64bit sticky_reg_bank_64bit_i4 (
    .\dec-word-in ( s3 ),
    .\word-flush ( \word-flush  ),
    .\master-reset ( \master-sent-rst  ),
    .presence( \word-presence-0-63  )
  );
  // bank64-127
  sticky_reg_bank_64bit sticky_reg_bank_64bit_i5 (
    .\dec-word-in ( s2 ),
    .\word-flush ( \word-flush  ),
    .\master-reset ( \master-sent-rst  ),
    .presence( \word-presence-64-127  )
  );
  // bank-128-191
  sticky_reg_bank_64bit sticky_reg_bank_64bit_i6 (
    .\dec-word-in ( s1 ),
    .\word-flush ( \word-flush  ),
    .\master-reset ( \master-sent-rst  ),
    .presence( \word-presence-128-191  )
  );
  // bank192-255
  sticky_reg_bank_64bit sticky_reg_bank_64bit_i7 (
    .\dec-word-in ( s0 ),
    .\word-flush ( \word-flush  ),
    .\master-reset ( \master-sent-rst  ),
    .presence( \word-presence-192-255  )
  );
  assign \punct-presence [0] = s4;
  assign \punct-presence [1] = s5;
  assign \punct-presence [2] = s6;
endmodule

